#*****************************************************************************************************
# please mention the added script in above.
# below comments should be in bottom in this script.

# Go to root folder
cd $EB2/../../
ROOT_DIR=`pwd`
PATCH_LIST_NAME="PatchListFile_${PRODUCT}.list"

cd ${ROOT_DIR}/05_Implement

rm -f $EB2/$PATCH_LIST_NAME
for PATCH_ITEM in ${PATCH_ITEMS[@]}
do
	PATCH_ITEM_TOP=`echo "$PATCH_ITEM" | awk '{print substr($0,1,1);}'`
	if [ ! "$PATCH_ITEM_TOP" = "#" -a -e $PATCH_ITEM ]; then
		echo "${PATCH_ITEM##*/05_Implement/}" >> $EB2/$PATCH_LIST_NAME
	fi
done

if [ -e $EB2/$PATCH_LIST_NAME ];then
	tar zcf SYSROM_SRC_tmp.tar.gz -T $EB2/$PATCH_LIST_NAME

	# Create patch folder
	cd $ROOT_DIR
	rm -rf patch
	mkdir -p patch/object
	mkdir -p patch/source
	tar zxvf ${ROOT_DIR}/05_Implement/SYSROM_SRC_tmp.tar.gz -C ${ROOT_DIR}/patch/object
	rm -f ${ROOT_DIR}/05_Implement/SYSROM_SRC_tmp.tar.gz
	tar zcf ${ROOT_DIR}/SYSROM_SRC_PATCH_ITEM_${PRODUCT}.tar.gz patch

	echo "### Creating a patch folder is complete. ###"
else
	echo "### ${PATCH_LIST_NAME} : No such file. ###"
fi

#To come back to SYSROM_SRC folder
cd $EB2
